file.content:
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
            record["output"], dict
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    mode = _log_mode(log["config"])
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if mode in ("stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode == "security_check":
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        mode = _log_mode(config)
        if mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_record_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_record_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_record_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_record_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        ForwardWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
    ):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path,
    max_events,
    max_log_bytes,
    max_output_bytes,
    max_replay_work,
    expected_sha256=None,
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        # 外部承诺先于事件数与一切语义重放：EXPECTED 须是调用方从成功
        # record 产物顶层 sha256 独立保存的值，绝不取自待重放 LOG。仅改
        # 帧并重算 LOG 内摘要的等价重写虽能通过内部自洽校验，仍因外部
        # 承诺不符在此失败（stdout 空、LOG 不动）
        if expected_sha256 is not None and expected_sha256 != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        mode = _log_mode(config)
        if mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_replay_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_replay_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_replay_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_replay_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_replay_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        ForwardWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
    ):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
        cost = 1 + len(value)
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(value):
            remaining = _diff_size_charge(value[key], remaining)
        return remaining
    if isinstance(value, list):
        if remaining < 1:
            raise DiffWorkLimit
        remaining -= 1
        for item in value:
            remaining = _diff_size_charge(item, remaining)
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    return remaining - 1


def _diff_work(old, new, remaining):
    """按工作量公式无副作用预演 D，返回剩余额度（耗尽为 0）。

    两值均为对象时计 1+并集键数，共有键递归计 D，单侧键计该侧 S；
    其余（含数组整体）计 1+S(旧值)+S(新值)。键按 Unicode 码点升序
    累计，递归逐层传递剩余额度；等于上限合法，首次超过即抛
    DiffWorkLimit，此后不再访问后续元素、键值或单侧子树。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        cost = 1 + len(set(old) | set(new))
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(set(old) | set(new)):
            if key in old and key in new:
                remaining = _diff_work(old[key], new[key], remaining)
            else:
                remaining = _diff_size_charge(
                    old[key] if key in old else new[key], remaining
                )
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    remaining -= 1
    remaining = _diff_size_charge(old, remaining)
    return _diff_size_charge(new, remaining)


def _cmd_config_diff(
    old_path,
    new_path,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        # 先打开两文件，任一失败即停；均可读后按 OLD、NEW 顺序分块读
        with open(old_path, "rb") as old_handle, open(
            new_path, "rb"
        ) as new_handle:
            old_raw = _read_limited(old_handle, max_input_bytes)
            if old_raw is None:
                _fail("input_limit")
                return 5
            new_raw = _read_limited(new_handle, max_input_bytes)
            if new_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        old_config = parse_json(old_raw)
        new_config = parse_json(new_raw)
        # 两份均按既有 port-security 契约全量解析校验
        validate_security_config(old_config)
        validate_security_config(new_config)
        # 语义校验后先无副作用预演根值 D；首次超过即停止，不生成差异
        _diff_work(old_config, new_config, max_diff_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("diff_work_limit")
        return 5
    changes = []
    _diff_collect(old_config, new_config, "", changes)
    result = {"equal": not changes, "changes": changes}
    payload = _result_bytes(result)
    # 输出字节上界（含末尾 LF）写出前判定；等于上限合法，超限时 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


def _cmd_config_export(
    config_path,
    max_export_work=DEFAULT_MAX_EXPORT_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        with open(config_path, "rb") as config_handle:
            # 仅读取一个 CONFIG；分块读取与字节边界沿用 config-diff
            config_raw = _read_limited(config_handle, max_input_bytes)
            if config_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        config = parse_json(config_raw)
        # 按既有 port-security 契约全量解析校验（编码、JSON、语义）
        validate_security_config(config)
        # 语义校验后先无副作用预演根值 S；等于上限合法，首次超过即停止，
        # 不构造导出文档。S 与遍历次序（对象键按 Unicode 码点升序）沿用
        # config-diff 的 _diff_size_charge
        _diff_size_charge(config, max_export_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("export_work_limit")
        return 5
    canonical = _canonical(config)
    # config 单独按紧凑 UTF-8 口径编码并加 LF 后的 SHA-256 小写十六进制
    config_payload = _result_bytes(canonical)
    digest = hashlib.sha256(config_payload).hexdigest()
    result = {"schema": 1, "config": canonical, "sha256": digest}
    payload = _result_bytes(result)
    # 输出字节上界（含末尾 LF）写出前判定；等于上限合法，超限时 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


SNAPSHOT_KEYS = ("schema", "config", "sha256")


def _cmd_config_import(
    snapshot_path,
    output_path,
    max_import_work=DEFAULT_MAX_IMPORT_WORK,
    max_input_bytes=CONFIG_IMPORT_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 CONFIG_IMPORT_MAX_OUTPUT_BYTES
        max_output_bytes = CONFIG_IMPORT_MAX_OUTPUT_BYTES
    try:
        with open(snapshot_path, "rb") as snapshot_handle:
            # 仅读取一个 SNAPSHOT；分块读取与字节边界沿用 config-export，
            # 原始字节（含空白）计入 IN，等于上限合法
            snapshot_raw = _read_limited(snapshot_handle, max_input_bytes)
            if snapshot_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        snapshot = parse_json(snapshot_raw)
        # 键恰为 schema,config,sha256（键序不限）；schema 为整数 1
        if not isinstance(snapshot, dict) or frozenset(snapshot) != frozenset(
            SNAPSHOT_KEYS
        ):
            raise InvalidInput("bad snapshot")
        if not _is_int(snapshot["schema"]) or snapshot["schema"] != 1:
            raise InvalidInput("bad snapshot schema")
        config = snapshot["config"]
        # 按既有 port-security 契约全量解析校验（编码、JSON、语义）
        validate_security_config(config)
        # C：config 规范化后按紧凑 UTF-8 口径编码并加 LF
        canonical = _canonical(config)
        payload = _result_bytes(canonical)
        # sha256 为 C 的 SHA-256 小写 64 位十六进制；不符即非法输入
        digest = snapshot["sha256"]
        if (
            not isinstance(digest, str)
            or hashlib.sha256(payload).hexdigest() != digest
        ):
            raise InvalidInput("bad snapshot sha256")
        # 全部非法输入判定后，按 config-export 同一公式无副作用预演 S；
        # 等于上限合法，首次超过即停止，不触碰 OUTPUT
        _diff_size_charge(config, max_import_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("import_work_limit")
        return 5
    # C 含 LF 不得超过 OUT；等于上限合法，超限时绝不触碰 OUTPUT
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    try:
        _atomic_write(output_path, payload)  # 成功原子替换 OUTPUT 为 C
    except OSError:
        _fail("file_not_found")
        return 3
    return 0  # 成功时 stdout 为空


def _cmd_frame_check(
    config_path,
    frames_path,
    max_config_bytes,
